/*
 * SolutionsHub — CodeBlue Technology solutions-consulting quoting tool
 * app.js
 *
 * This file is a near-verbatim port of the "Component" class and its catalog
 * data (PILLARS, SCOPE_LIBRARY, AUTO_SOFTWARE, OPTIONAL_ADDONS, FIREWALL_MODELS,
 * the Zultys phone catalog, embedded product/logo images, and every pricing /
 * business-logic method) from the original Claude "design canvas" artifact
 * ("CodeBlue Solutions Walkthrough"). The catalog data and pricing formulas
 * were NOT modified — only the runtime scaffolding around them changed:
 *
 *   - `DCLogic` below is a tiny stand-in for the canvas runtime's base class.
 *     It only provides `this.props`, `this.state`, and `this.setState()`
 *     (shallow merge + re-render), which is all the original Component ever
 *     used from it (confirmed by inspection: no lifecycle hooks were used).
 *   - `Component.renderVals()` is unchanged: it is the same "view model
 *     builder" method the canvas runtime called after every render. Our own
 *     runtime.js calls it the same way and diffs the result against the DOM.
 *   - The `sc-if` / `sc-for` / `{{path}}` template syntax it feeds is parsed
 *     and patched by runtime.js instead of the canvas's internal DOM patcher.
 *
 * KNOWN LIMITATION — AI invoice reading (Managed IT "current invoice" upload):
 *   `miAnalyzeInvoiceFile()` originally called `window.claude.use('sample')`,
 *   a capability that only exists inside a claude.ai artifact sandbox, to have
 *   Claude read a PDF invoice and extract line items. That capability does not
 *   exist in this standalone deployment. The method is ported UNCHANGED and
 *   already defensively checks `window.claude` — since that global will not
 *   exist here, it now always falls straight into the pre-existing
 *   status: 'unavailable' branch with the message "AI invoice reading isn't
 *   available in this view — enter the total manually above." The rest of the
 *   Managed IT "current spend" comparison flow (manual entry) is fully intact.
 *   No PDF.js is loaded because the only code path that loads it
 *   (ensurePdfJs/renderPdfPagesToImages) is unreachable without window.claude.
 *
 * ADDED — Email Quote to Customer:
 *   The original artifact could only "Copy Quote for Email" to the clipboard
 *   (no server to send from). This port adds `sendQuoteByEmail()`, which POSTs
 *   the same quote text to mail/send-quote.php (a small dependency-free PHP
 *   SMTP sender) so account managers can actually email a customer from the
 *   Solution Summary screen. See mail/config.sample.php for setup.
 */

'use strict';

// Minimal base class replacing the canvas runtime's DCLogic. The ported
// Component class only ever used this.props, this.state and this.setState().
class DCLogic {
  constructor(props) {
    this.props = props || {};
    this.state = {};
    this._onChange = null; // wired up by runtime.js after construction
  }
  setState(patch) {
    if (typeof patch === 'function') patch = patch(this.state);
    Object.assign(this.state, patch);
    if (typeof this._onChange === 'function') this._onChange();
  }
}


