  computeManagedIT() {
    var mi = this.state.managedIT;
    var d = mi.devices;
    var minutesTotal = 0;
    DEVICE_TYPES.forEach(function (dt) { minutesTotal += (d[dt.id] || 0) * dt.minutes; });
    minutesTotal += (mi.members || 0) * M365_USER_MINUTES;
    var laborMonthly = (minutesTotal / 60) * mi.hourlyRate;
    var mdmType = DEVICE_TYPES.find(function (dt) { return dt.id === 'mdm'; });
    var mdmMgmtMonthly = (d.mdm || 0) * (mdmType ? mdmType.mgmtFee : 8.00);
    var supportMonthly = laborMonthly + mdmMgmtMonthly;
    var perMemberPrice = mi.members > 0 ? (supportMonthly / mi.members) : 0;

    var isAlaCarte = mi.approach === 'alacarte';
    var alaCarteSoftware = mi.alaCarteSoftware || {};
    var softwareMonthly = 0;
    var sentinelQty = 0;
    if (isAlaCarte) {
      AUTO_SOFTWARE.forEach(function (item) {
        var qty = alaCarteSoftware[item.id] || 0;
        softwareMonthly += qty * item.rate;
      });
      sentinelQty = alaCarteSoftware.sentinelone || 0;
    } else {
      AUTO_SOFTWARE.forEach(function (item) {
        var qty = 0;
        item.qtyFrom.forEach(function (k) { qty += (d[k] || 0); });
        softwareMonthly += qty * item.rate;
      });
      sentinelQty = (d.workstation || 0) + (d.server || 0);
    }
    var addons = mi.addons;
    OPTIONAL_ADDONS.forEach(function (a) { softwareMonthly += (addons[a.id] || 0) * a.rate; });

    var hardwareMonthly = 0;
    if (mi.firewallSku) {
      var fw = FIREWALL_MODELS.find(function (f) { return f.sku === mi.firewallSku; });
      if (fw) hardwareMonthly = fw.rate;
    }

    var onboardingTotal = 0;
    DEVICE_TYPES.forEach(function (dt) { onboardingTotal += (d[dt.id] || 0) * dt.onboardFee; });
    var ccobQty = sentinelQty + (addons.cyberSecPro || 0);
    onboardingTotal += ccobQty * CCOB_FEE;
    if (mi.members > 0) onboardingTotal += M365_ONBOARD_FEE;
    var wsBackupAddon = OPTIONAL_ADDONS.find(function (a) { return a.id === 'veeamWsBackup'; });
    var srvBackupAddon = OPTIONAL_ADDONS.find(function (a) { return a.id === 'veeamSrvBackup'; });
    if ((addons.veeamWsBackup || 0) > 0) onboardingTotal += (wsBackupAddon ? wsBackupAddon.onboardFee : 85);
    if ((addons.veeamSrvBackup || 0) > 0) onboardingTotal += (srvBackupAddon ? srvBackupAddon.onboardFee : 85);
    if (mi.approach === 'peoplefirst' && mi.members > 0) onboardingTotal += MEMBER_SETUP_FEE;

    var onboardingBeforeDiscount = onboardingTotal;
    var onboardingDiscountPct = (mi.approach === 'peoplefirst') ? (mi.onboardingDiscountPct || 0) : 0;
    if (onboardingDiscountPct > 0) {
      onboardingTotal = onboardingTotal * (1 - onboardingDiscountPct / 100);
    }

    return {
      minutesTotal: minutesTotal,
      supportMonthly: supportMonthly,
      perMemberPrice: perMemberPrice,
      softwareMonthly: softwareMonthly,
      hardwareMonthly: hardwareMonthly,
      onboardingBeforeDiscount: onboardingBeforeDiscount,
      onboardingDiscountPct: onboardingDiscountPct,
      onboardingTotal: onboardingTotal
    };
  }

  addManagedITToSolution() {
    var svc = this.findService('it', 'managed-it');
    var pillarObj = this.findPillar('it');
    if (!svc || !pillarObj) return;
    var mi = this.state.managedIT;
    var nums = this.computeManagedIT();
    var approachLabel = mi.approach === 'peoplefirst' ? 'PeopleFirst Membership' : 'À La Carte Managed Care';
    var supportPiece = mi.approach === 'peoplefirst'
      ? ('$' + nums.perMemberPrice.toFixed(2) + '/member/mo')
      : ('$' + nums.supportMonthly.toFixed(2) + '/mo support');
    var detail = 'Software $' + nums.softwareMonthly.toFixed(2) + '/mo · Hardware $' + nums.hardwareMonthly.toFixed(2) + '/mo · ' + supportPiece + ' · $' + nums.onboardingTotal.toFixed(2) + ' onboarding';
    var sel = Object.assign({}, this.state.selections);
    sel[svc.id] = {
      pillarId: pillarObj.id, pillarName: pillarObj.name, serviceName: svc.name,
      optionId: approachLabel, optionLabel: approachLabel + ' — ' + detail, optionDetail: detail,
      outcomeTags: svc.outcome,
      note: this.state.categoryNotes[svc.id] || ''
    };
    this.setState({ selections: sel });
  }

  getPartsEntry(categoryId, productId) {
    var byCategory = this.state.partsSelections[categoryId] || {};
    return byCategory[productId] || { qty: 0, chips: {}, ranges: {} };
  }

  updatePartsEntry(categoryId, productId, patch) {
    var all = Object.assign({}, this.state.partsSelections);
    var byCategory = Object.assign({}, all[categoryId] || {});
    var entry = byCategory[productId] || { qty: 0, chips: {}, ranges: {} };
    var next = Object.assign({}, entry, patch);
    if (patch.chips) next.chips = Object.assign({}, entry.chips, patch.chips);
    if (patch.ranges) next.ranges = Object.assign({}, entry.ranges, patch.ranges);
    byCategory[productId] = next;
    all[categoryId] = byCategory;
    this.setState({ partsSelections: all });
  }

  incPartsQty(categoryId, productId, delta) {
    var entry = this.getPartsEntry(categoryId, productId);
    var qty = (entry.qty || 0) + delta;
    if (qty < 0) qty = 0;
    if (qty > 99) qty = 99;
    this.updatePartsEntry(categoryId, productId, { qty: qty });
  }

  choosePartsChip(categoryId, productId, optionId, choiceId) {
    var entry = this.getPartsEntry(categoryId, productId);
    var current = (entry.chips || {})[optionId];
    var chipPatch = {};
    chipPatch[optionId] = (current === choiceId) ? null : choiceId;
    this.updatePartsEntry(categoryId, productId, { chips: chipPatch });
  }

  incPartsRange(categoryId, productId, optionId, delta, min, max, step, autoBaseline) {
    var entry = this.getPartsEntry(categoryId, productId);
    var stored = (entry.ranges || {})[optionId] || 0;
    var current = stored > 0 ? stored : (autoBaseline || 0);
    var next;
    if (delta > 0) {
      next = (current <= 0) ? (min > 0 ? min : step) : Math.min(max, current + step);
    } else {
      next = (current - step < min) ? 0 : (current - step);
    }
    var rangePatch = {};
    rangePatch[optionId] = next;
    this.updatePartsEntry(categoryId, productId, { ranges: rangePatch });
  }

  setPartsBillingMode(categoryId, mode, hiddenProductIds) {
    var modes = Object.assign({}, this.state.partsBillingMode);
    modes[categoryId] = mode;
    var all = Object.assign({}, this.state.partsSelections);
    var byCategory = Object.assign({}, all[categoryId] || {});
    (hiddenProductIds || []).forEach(function (pid) {
      if (byCategory[pid]) {
        byCategory[pid] = Object.assign({}, byCategory[pid], { qty: 0 });
      }
    });
    all[categoryId] = byCategory;
    this.setState({ partsBillingMode: modes, partsSelections: all });
  }

